# One frame for a single pixel. The BOOT button picks the mode (flow 'mode').
B = 64       # brightness cap, 0-255

f = context.get('f', 0) + 1
context.set('f', f)
mode = flow.get('mode', 0)

def wheel(p):
    # Colour wheel 0-255 -> (r, g, b): red -> green -> blue -> red.
    p = p % 256
    if p < 85:
        return (255 - p * 3, p * 3, 0)
    if p < 170:
        p -= 85
        return (0, 255 - p * 3, p * 3)
    p -= 170
    return (p * 3, 0, 255 - p * 3)

def pack(rgb, level):
    # (r, g, b) at level 0-255 of the brightness cap -> 0xRRGGBB
    r, g, b = rgb
    k = B * level // 255
    return ((r * k // 255) << 16) | ((g * k // 255) << 8) | (b * k // 255)

if mode == 0:
    # Colour cycle: once round the wheel about every 4 seconds.
    msg['payload'] = pack(wheel(f * 3), 255)
elif mode == 1:
    # Breathe: fade up and down, a new colour each breath.
    t = f % 100
    level = t * 255 // 50 if t < 50 else (100 - t) * 255 // 50
    msg['payload'] = pack(wheel((f // 100) * 40), level)
else:
    # Police: two red flashes, two blue flashes.
    t = f % 20
    on = t in (0, 2, 10, 12)
    msg['payload'] = pack((255, 0, 0) if t < 10 else (0, 0, 255), 255 if on else 0)
return msg
